use galley.kitchen;
use galley.menu;

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let dishes = menu.board();
    var i = 0;
    while i < dishes.len() {
        if i > 0 {
            io.write(text: ";")?;
        }
        let dish = dishes.get(index: i)?;
        kitchen.serve(io: io, dish: dish)?;
        i = i + 1;
    }
    return Ok(unit);
}

