use relay.feed;

pub fn publish(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let received = feed.frames();
    var total = 0;
    var i = 0;
    while i < received.len() {
        let value = match feed.decode(frame: received.get(index: i)?) {
            Ok(n) => n,
            Err(_) => 0,
        };
        total = total + value;
        i = i + 1;
    }
    feed.emit(io: io, total: total)?;
    return Ok(unit);
}

