use stable.herd;
use stable.ledger;

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let ponies = herd.lineup();
    var entries: List<String> = [];

    var i = 0;
    while i < ponies.len() {
        let fed = herd.feed(pony: ponies.get(i)?, scoops: 3);
        entries.push(item: ledger.entry(fed));
        i = i + 1;
    }

    io.write(text: entries.join(sep: ","))?;
    return Ok(unit);
}

